python3 - <<'PY'
import json, re

SYSTEM_CMDS = re.compile(r'\b(npm run build|npx tsc|tsc\b|npm test|vitest|npm start|node dist|curl |expo export|expo-doctor|jest\b|npx expo|npm run )\b', re.I)

def analyze(path, label):
    print('='*80)
    print(label)
    in_paso2=False
    cmds=[]
    files=[]
    with open(path) as f:
        for i,line in enumerate(f):
            o=json.loads(line)
            t=o.get('tipo')
            if t=='paso_inicio' and o.get('orden')==2:
                in_paso2=True; continue
            if t=='paso_fin' and o.get('orden')==2:
                in_paso2=False; continue
            if not in_paso2 or t!='evento_cli':
                continue
            if o.get('tipo_cli')!='item.completed':
                continue
            item=(o.get('payload') or {}).get('item') or {}
            it=item.get('type')
            if it=='command_execution':
                cmds.append({
                    'L': i,
                    'id': item.get('id'),
                    'command': item.get('command'),
                    'exit': item.get('exit_code'),
                    'status': item.get('status'),
                    'out': (item.get('aggregated_output') or '')[:300]
                })
            elif it=='file_change':
                files.append({'L': i, 'item': item})
    print(f'completed commands: {len(cmds)}  file_changes: {len(files)}')
    print('\nFILE CHANGES:')
    for fc in files:
        print(json.dumps(fc, ensure_ascii=False)[:1000])
    print('\nSYSTEM-LIKE COMMANDS:')
    for c in cmds:
        cmd=c['command'] or ''
        if SYSTEM_CMDS.search(cmd) or any(x in cmd for x in ['npm ','vitest','jest','tsc','expo','curl','node ']):
            print(f"L{c['L']} exit={c['exit']} status={c['status']}\n  CMD: {cmd[:500]}\n  OUT: {c['out'][:250]}\n")
    print('\nALL COMMANDS (short):')
    for c in cmds:
        cmd=c['command'] or ''
        # shorten
        short=cmd.replace('/bin/sh -lc ', '')
        if short.startswith('"') or short.startswith("'"):
            pass
        print(f"L{c['L']} e={c['exit']} {short[:180]}")

for p,l in [('logs/backend.jsonl','BACKEND'),('logs/web.jsonl','WEB'),('logs/mobile.jsonl','MOBILE')]:
    analyze(p,l)
    print()
PY

