  if (error instanceof ApiError) {
    reply.status(error.status).send(error.toBody());
    return;
  }
  const fastifyError = error as Error & { code?: string; statusCode?: number };
  if (
    fastifyError.code === "FST_ERR_CTP_INVALID_MEDIA_TYPE" ||
    fastifyError.code === "FST_ERR_CTP_EMPTY_JSON_BODY" ||
    fastifyError.code === "FST_ERR_CTP_BODY_TOO_LARGE" ||
    fastifyError.statusCode === 400
  ) {
    const apiError = validationError([{ field: "body", message: "JSON inválido o Content-Type no soportado" }]);
    reply.status(apiError.status).send(apiError.toBody());
    return;
  }
  const apiError = new ApiError("INTERNAL_ERROR");
  reply.status(apiError.status).send(apiError.toBody());
});

app.setNotFoundHandler((request, reply) => {
  const path = request.url.split("?", 1)[0] ?? request.url;
