import { useCallback, useEffect, useState } from "react";
import { ApiResponseError, validateSession } from "./api";
import { LoginPage } from "./LoginPage";
import {
  clearSession,
  navigate,
  readSession,
  SESSION_EXPIRED_EVENT,
  sessionIsExpired,
} from "./session";

type AppState = "checking" | "login" | "authenticated" | "validation-error";

export function App() {
  const [state, setState] = useState<AppState>("checking");

  const checkPersistedSession = useCallback(async () => {
    setState("checking");
    const session = readSession();
    if (!session || sessionIsExpired(session)) {
      clearSession();
      navigate("/login", true);
      setState("login");
      return;
    }
    try {
      await validateSession(session);
      navigate("/trading", true);
      setState("authenticated");
    } catch (error) {
      if (error instanceof ApiResponseError && error.code === "UNAUTHENTICATED") {
        clearSession();
        navigate("/login", true);
        setState("login");
        return;
      }
      setState("validation-error");
    }
  }, []);

  useEffect(() => {
    void checkPersistedSession();
    const handleExpiration = () => setState("login");
    window.addEventListener(SESSION_EXPIRED_EVENT, handleExpiration);
    return () => window.removeEventListener(SESSION_EXPIRED_EVENT, handleExpiration);
  }, [checkPersistedSession]);

  const handleAuthenticated = () => {
    navigate("/trading");
    setState("authenticated");
  };

  if (state === "checking") {
    return (
      <main className="centered-state" aria-live="polite">
        <div className="brand-mark" aria-hidden="true"><span>A</span></div>
        <span className="spinner spinner-large" aria-hidden="true" />
        <p>Validando sesión…</p>
      </main>
    );
  }

  if (state === "validation-error") {
    return (
      <main className="centered-state">
        <div className="brand-mark" aria-hidden="true"><span>A</span></div>
        <h1>No se pudo validar tu sesión</h1>
        <p>No se pudo conectar, reintentá.</p>
        <button className="primary-button compact" type="button" onClick={() => void checkPersistedSession()}>
          Reintentar
        </button>
      </main>
    );
  }

  if (state === "authenticated") {
    return (
      <main className="centered-state" aria-live="polite">
        <div className="brand-mark" aria-hidden="true"><span>A</span></div>
        <h1>Sesión iniciada</h1>
        <p>Preparando la vista de trading…</p>
      </main>
    );
  }

  return <LoginPage onAuthenticated={handleAuthenticated} />;
}

