export interface Session {
  token: string;
  expiresAt: string;
}

export const SESSION_STORAGE_KEY = "axis.session.v1";
const EXPIRATION_NOTICE_KEY = "axis.session-expired";
export const SESSION_EXPIRED_EVENT = "axis:session-expired";

let memorySession: Session | null = null;

function isSession(value: unknown): value is Session {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
  const candidate = value as Record<string, unknown>;
  return typeof candidate.token === "string" && candidate.token.length > 0
    && typeof candidate.expiresAt === "string"
    && Number.isFinite(Date.parse(candidate.expiresAt));
}

export function persistSession(session: Session): void {
  memorySession = { ...session };
  localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(session));
}

export function readSession(): Session | null {
  if (memorySession) return { ...memorySession };
  const raw = localStorage.getItem(SESSION_STORAGE_KEY);
  if (!raw) return null;
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!isSession(parsed)) {
      clearSession();
      return null;
    }
    memorySession = parsed;
    return { ...parsed };
  } catch {
    clearSession();
    return null;
  }
}

export function clearSession(): void {
  memorySession = null;
  localStorage.removeItem(SESSION_STORAGE_KEY);
}

export function sessionIsExpired(session: Session, now = Date.now()): boolean {
  return now >= Date.parse(session.expiresAt);
}

