      <View style={styles.networkRow}>
        <View style={[styles.statusDot, socketStatus === "live" && styles.statusLive]} />
        <Text style={styles.networkText}>Sesión {SOCKET_LABELS[socketStatus].toLowerCase()}</Text>
      </View>

      <Text style={styles.label}>Activo</Text>
      <View style={styles.segment}>
90→        {(["ETH", "USDC"] as const).map((candidate) => (
          <Pressable
            accessibilityRole="button"
            key={candidate}
            onPress={() => setAsset(candidate)}
            style={[styles.segmentButton, asset === candidate && styles.segmentActive]}
          >
            <Text style={[styles.segmentText, asset === candidate && styles.segmentTextActive]}>
              {candidate === "USDC" ? "USDC-mock" : "ETH"}
            </Text>
100→          </Pressable>
        ))}
      </View>

      <View style={styles.card}>
        <View style={styles.chainBadge}>
          <Text style={styles.chainBadgeText}>SEPOLIA · CHAIN ID 11155111</Text>
        </View>
        {loading ? (
          <View style={styles.centerState}>
110→            <ActivityIndicator color="#46d7b0" size="large" />
            <Text style={styles.muted}>Obteniendo tu dirección…</Text>
          </View>
        ) : error ? (
          <View style={styles.centerState}>
