              <Text style={styles.retryText}>Reintentar</Text>
            </Pressable>
          </View>
120→        ) : deposit ? (
          <>
            <Text style={styles.instruction}>
              Enviá únicamente {deposit.asset === "USDC" ? "USDC-mock" : "ETH"} por la red Sepolia.
            </Text>
            <View style={styles.qrFrame} testID="deposit-qr">
              <QRCode
                backgroundColor="#ffffff"
                color="#07111f"
                quietZone={8}
130→                size={210}
                value={depositQrValue(deposit)}
              />
            </View>
            <Text style={styles.addressLabel}>Tu dirección de depósito</Text>
            <Text selectable style={styles.address} testID="deposit-address">{deposit.address}</Text>
            <Pressable accessibilityRole="button" onPress={() => { void copy(); }} style={styles.copyButton}>
              <Text style={styles.copyButtonText}>{copied ? "Dirección copiada" : "Copiar dirección"}</Text>
            </Pressable>
            <Text style={styles.note}>
140→              ETH y USDC-mock llegan a esta misma dirección. El QR ya incluye la red y el activo elegidos.
            </Text>
          </>
        ) : null}
      </View>
    </ScrollView>
  );
