1→import {
  createContext,
  type PropsWithChildren,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
10→} from "react";
import { AppState } from "react-native";
import { loginRequest, logoutRequest } from "../api/client";
import { sessionStorage } from "./session-storage";

type SessionPhase = "restoring" | "guest" | "authenticated";

interface AuthContextValue {
  phase: SessionPhase;
  token: string | null;
20→  login(email: string, password: string): Promise<void>;
  logout(): Promise<void>;
  handleUnauthenticated(): Promise<void>;
}

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

export function AuthProvider({ children }: PropsWithChildren) {
  const [phase, setPhase] = useState<SessionPhase>("restoring");
  const [token, setToken] = useState<string | null>(null);
30→  const tokenRef = useRef<string | null>(null);
  const storageReadFailedRef = useRef(false);
  const logoutPromiseRef = useRef<Promise<void> | null>(null);

  const restore = useCallback(async () => {
    try {
      const restored = await sessionStorage.read();
      storageReadFailedRef.current = false;
      tokenRef.current = restored;
      setToken(restored);
40→      setPhase(restored ? "authenticated" : "guest");
    } catch {
      storageReadFailedRef.current = true;
      tokenRef.current = null;
      setToken(null);
      setPhase("guest");
    }
  }, []);

  useEffect(() => {
50→    void restore();
  }, [restore]);

  useEffect(() => {
    const subscription = AppState.addEventListener("change", (nextState) => {
      if (nextState === "active" && storageReadFailedRef.current && tokenRef.current === null) {
        void restore();
      }
    });
    return () => subscription.remove();
60→  }, [restore]);

  const handleUnauthenticated = useCallback(async (): Promise<void> => {
    if (logoutPromiseRef.current) return logoutPromiseRef.current;
    if (tokenRef.current === null) return;

    const operation = (async () => {
      try {
        await sessionStorage.remove();
      } catch {
70→        // Memory is still cleared. A later launch treats an inaccessible store as no session.
      } finally {
        tokenRef.current = null;
        setToken(null);
        setPhase("guest");
      }
    })();
    logoutPromiseRef.current = operation;
    try {
      await operation;
80→    } finally {
      if (logoutPromiseRef.current === operation) logoutPromiseRef.current = null;
    }
  }, []);

  const login = useCallback(async (email: string, password: string): Promise<void> => {
    const response = await loginRequest(email, password);
    await sessionStorage.write(response.token);
    tokenRef.current = response.token;
    setToken(response.token);
90→    setPhase("authenticated");
  }, []);

  const logout = useCallback(async (): Promise<void> => {
    const currentToken = tokenRef.current;
    if (currentToken) {
      try {
        await logoutRequest(currentToken, handleUnauthenticated);
      } catch {
        // Explicit logout remains local and safe when the server or network is unavailable.
100→      }
    }
    await handleUnauthenticated();
  }, [handleUnauthenticated]);

  const value = useMemo<AuthContextValue>(() => ({
    phase,
    token,
    login,
    logout,
110→    handleUnauthenticated,
  }), [handleUnauthenticated, login, logout, phase, token]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
  const value = useContext(AuthContext);
  if (!value) throw new Error("useAuth debe usarse dentro de AuthProvider");
  return value;
120→}

