+  for (;;) {
+    try {
+      await SecureStore.deleteItemAsync(SESSION_TOKEN_KEY);
+      return;
+    } catch {
+      await delay(retryDelay);
+      retryDelay = Math.min(retryDelay * 2, DELETE_RETRY_MAX_MS);
+    }
